<template>
 <view class="secondary-page has-footer" :class="{'admins-page':view==='ADMINS'}">
  <view class="members-nav"><NativeStatusSpacer/><button class="nav-back" @tap="goBack">‹</button><text>{{view==='ADMINS'?'组织管理员设置':'组织成员'}}</text></view>
  <template v-if="view==='ADMINS'">
   <view class="section">
    <view class="segmented"><button :class="{active:adminTab==='SCHOOL'}" :disabled="busy||!schoolOrg" @tap="switchAdminTab('SCHOOL')">学校管理员</button><button :class="{active:adminTab==='INSTITUTION'}" :disabled="busy||!institutionOrg" @tap="switchAdminTab('INSTITUTION')">机构管理员</button></view>
    <text v-if="error" class="error">{{error}}</text>
    <view v-if="busy" class="empty">正在处理…</view>
    <view v-for="item in admins" :key="item.id" class="row">
     <view class="person"><PrototypeIcon name="user" :size="35"/></view>
     <view class="person-copy"><view class="row-top"><text class="name">{{item.displayName||item.username}}</text><text v-if="item.owner" class="badge owner">负责人</text><text v-else class="badge class-admin">{{adminOrg?.typeCode==='SCHOOL'?'学校管理员':'机构管理员'}}</text></view><text v-if="item.organizationNames?.length" class="meta">{{item.organizationNames.join(' / ')}}</text></view>
     <text :class="['admin-state',item.status==='ENABLED'?'enabled':'disabled']">{{item.status==='ENABLED'?'已启用':'未启用'}}</text>
    </view>
    <view v-if="!busy&&!admins.length&&!error" class="empty"><PrototypeIcon name="people" tone="muted" :size="64"/><text>暂无管理员</text></view>
   </view>
   <view class="section add-admin-card" @tap="openMemberPicker">
    <text class="add-plus">＋</text>
    <text class="add-title">添加管理员</text>
    <text class="add-note">仅可设置本组织内的管理员，不可跨学校或其他机构设置</text>
   </view>
   <view class="bottom-actions"><text class="small">管理员 {{admins.length}} 人</text></view>
  </template>
  <template v-else>
  <view class="section">
   <text class="field-label">当前组织</text>
   <view class="picker-field"><text>{{organization?.name||'请从我的组织重新进入'}}</text></view>
   <view class="segmented"><button :class="{active:side==='MEMBERS'}" :disabled="busy" @tap="switchSide('MEMBERS')">已加入</button><button v-if="can('ORG_MEMBER_ASSOCIATE')" :class="{active:side==='CANDIDATES'}" :disabled="busy" @tap="switchSide('CANDIDATES')">待加入</button></view>
   <view class="search-row"><PrototypeIcon name="people" :size="30"/><input v-model="keyword" placeholder="姓名、账号或手机号" :disabled="busy" @confirm="search"/><button class="secondary" :disabled="busy" @tap="search">查询</button></view>
  </view>
  <text v-if="error" class="error">{{error}}</text>
  <view class="section">
   <view v-if="!parent" class="back-row"><text class="back-link" @tap="backToAdmins">‹ 返回管理员列表</text></view>
   <view class="section-heading"><text class="section-title">{{side==='MEMBERS'?'组织成员':'待加入成员'}}</text><text class="small">共 {{total}} 人</text></view>
   <view v-if="busy" class="empty">正在处理…</view>
   <view v-for="item in items" :key="item.id" class="row">
    <view class="person"><PrototypeIcon name="user" :size="35"/></view>
    <view class="person-copy"><view class="row-top"><text class="name">{{item.displayName||item.username}}</text><text v-if="item.owner" class="badge owner">负责人</text><text v-else-if="item.administrator" class="badge">管理员</text></view><text class="meta">{{item.mobile||item.username}}</text><text v-if="item.organizationNames?.length" class="meta">{{item.organizationNames.join(' / ')}}</text></view>
    <checkbox v-if="!item.owner" :checked="selected.includes(item.id)" :disabled="busy" color="#184f40" @tap="toggle(item.id)"/>
   </view>
   <view v-if="!busy&&!items.length&&!error" class="empty"><PrototypeIcon name="people" tone="muted" :size="64"/><text>{{side==='MEMBERS'?'暂无组织成员':'暂无待加入成员'}}</text></view>
   <view class="pagination-state"><text v-if="loadingMore">正在加载更多</text><button v-else-if="appendError" @tap="loadMore">加载失败，点击重试</button><text v-else-if="items.length &amp;&amp; !hasMore">已经到底了</text></view>
  </view>
  <view class="bottom-actions"><text class="small">已选择 {{selected.length}} 人</text><view class="action-grid"><button v-if="side==='CANDIDATES'&&can('ORG_MEMBER_ASSOCIATE')" class="primary" :disabled="busy||!selected.length" @tap="act('members:associate')">加入组织</button><template v-if="side==='MEMBERS'"><button v-if="can('ORG_ADMIN_ASSIGN')" class="primary" :disabled="busy||!selected.length" @tap="act('administrators:assign')">设管理员</button><button v-if="can('ORG_ADMIN_REVOKE')" class="secondary" :disabled="busy||!selected.length" @tap="act('administrators:revoke')">撤销管理员</button><button v-if="can('ORG_MEMBER_REMOVE')" class="danger" :disabled="busy||!selected.length" @tap="act('members:remove')">移除</button></template></view></view>
  </template>
 </view>
</template>
<script setup lang="ts">
import PrototypePageHeader from "@/components/PrototypePageHeader.vue";
import {computed,ref} from 'vue';import NativeStatusSpacer from '@/components/NativeStatusSpacer.vue';import {onShow,onHide,onUnload,onLoad,onReachBottom} from '@dcloudio/uni-app';import PrototypeIcon from '@/components/PrototypeIcon.vue';import {getOrganizationSession} from '@/session/organization-session';import {request} from '@/api/http';import {getParentSession} from '@/session/parent-session';import {onboardingApi,type MyOrganization} from '@/api/organization-onboarding';import {organizationMembersApi,type OrganizationMember,type OrganizationAdmin,type MemberAction} from '@/api/organization-members';
const loadingMore=ref(false),hasMore=ref(false),appendError=ref('');let committedKeyword='';
const parent=ref(false);const session=()=>parent.value?getParentSession():getOrganizationSession();const meContext=(token:string)=>request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${token}`}});const organizations=ref<MyOrganization[]>([]),allOrgs=ref<MyOrganization[]>([]),organizationIndex=ref(0),permissions=ref<string[]>([]),side=ref<'MEMBERS'|'CANDIDATES'>('MEMBERS'),view=ref<'ADMINS'|'MEMBERS'>('MEMBERS'),adminTab=ref<'SCHOOL'|'INSTITUTION'>('SCHOOL'),admins=ref<OrganizationAdmin[]>([]),keyword=ref(''),items=ref<OrganizationMember[]>([]),selected=ref<string[]>([]),page=ref(1),total=ref(0),busy=ref(false),error=ref('');const organization=computed(()=>organizations.value[organizationIndex.value]);const schoolOrg=computed(()=>organization.value?.typeCode==='SCHOOL'?organization.value:undefined);const institutionOrg=computed(()=>organization.value?.typeCode==='TRAINING_INSTITUTION'?organization.value:undefined);const adminOrg=computed(()=>adminTab.value==='SCHOOL'?schoolOrg.value:institutionOrg.value);let epoch=0,requestedOrganization='';function expire(n:number,t:string){if(n!==epoch||valid(n,t))return;busy.value=false;items.value=[];admins.value=[];organizations.value=[];allOrgs.value=[];permissions.value=[];selected.value=[];error.value='当前组织已失效，请从我的组织重新进入';}const can=(code:string)=>permissions.value.includes(code);const valid=(n:number,t:string)=>{const stored=uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string};return n===epoch&&session()?.accessToken===t&&stored?.accessToken===t&&(!organization.value||stored.organizationId===organization.value.id);};
onLoad(q=>{parent.value=q?.identity==='parent';view.value=q?.identity==='parent'?'MEMBERS':'ADMINS';requestedOrganization=q?.organizationId||'';});function goBack(){uni.navigateBack();}function hide(){epoch++;loadingMore.value=false;hasMore.value=false;appendError.value='';busy.value=false;selected.value=[];items.value=[];admins.value=[];permissions.value=[];organizations.value=[];allOrgs.value=[];error.value="";total.value=0;}onHide(hide);onUnload(hide);
onShow(async()=>{permissions.value=[];organizations.value=[];allOrgs.value=[];items.value=[];admins.value=[];selected.value=[];const s=session();if(!s){uni.reLaunch({url:'/pages/unified-login/unified-login'});return;}const initial=uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string};if(initial?.accessToken!==s.accessToken||!initial.organizationId||(requestedOrganization&&requestedOrganization!==initial.organizationId)){busy.value=false;error.value='当前组织已失效，请从我的组织重新进入';return;}const n=++epoch;busy.value=true;error.value='';try{const [me,orgs]=await Promise.all([meContext(s.accessToken),onboardingApi.organizations(s.accessToken)]);if(!valid(n,s.accessToken)||(uni.getStorageSync('lingdong.selected-organization') as {organizationId?:string})?.organizationId!==initial.organizationId){if(n===epoch){busy.value=false;error.value='当前组织已失效，请从我的组织重新进入';}return;}permissions.value=me.permissionCodes;if(!can('ORG_MEMBER_READ'))throw new Error('当前账号没有组织成员查看权限');organizations.value=orgs.filter(o=>parent.value?o.typeCode==='FAMILY'&&o.canEnterFamily:o.canEnterInstitution);allOrgs.value=orgs;const stored=uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string};const id=stored?.accessToken===s.accessToken?stored.organizationId:'';if(!id||(requestedOrganization&&requestedOrganization!==id)||!organizations.value.some(o=>o.id===id)){organizations.value=[];allOrgs.value=[];throw new Error('当前组织已失效，请从我的组织重新进入');}organizations.value=organizations.value.filter(o=>o.id===id);organizationIndex.value=0;adminTab.value=organization.value?.typeCode==='TRAINING_INSTITUTION'?'INSTITUTION':'SCHOOL';view.value=parent.value?'MEMBERS':'ADMINS';}catch(e){if(valid(n,s.accessToken))error.value=e instanceof Error?e.message:'加载失败';}finally{if(valid(n,s.accessToken))busy.value=false;else expire(n,s.accessToken);}if(valid(n,s.accessToken)&&!error.value){if(view.value==='ADMINS')await loadAdmins();else await load();}});
async function load(){const s=session(),org=organization.value;if(!s||!org||busy.value)return;const n=++epoch;loadingMore.value=false;hasMore.value=false;appendError.value='';page.value=1;total.value=0;committedKeyword=keyword.value;const query=committedKeyword,querySide=side.value;busy.value=true;error.value='';selected.value=[];items.value=[];try{const result=await organizationMembersApi.list(s.accessToken,org.id,querySide,query,1);if(valid(n,s.accessToken)){items.value=result.items;page.value=result.page||1;total.value=result.total;hasMore.value=result.items.length>0&&page.value*(result.pageSize||20)<result.total;}}catch(e){if(valid(n,s.accessToken))error.value=e instanceof Error?e.message:'成员加载失败';}finally{if(valid(n,s.accessToken))busy.value=false;else expire(n,s.accessToken);}}
async function loadMore(){const s=session(),org=organization.value;if(!s||!org||busy.value||loadingMore.value||view.value!=='MEMBERS'||!hasMore.value||!valid(epoch,s.accessToken))return;const n=epoch,target=page.value+1,query=committedKeyword,querySide=side.value;loadingMore.value=true;appendError.value='';try{const result=await organizationMembersApi.list(s.accessToken,org.id,querySide,query,target);if(!valid(n,s.accessToken))return;const previousCount=items.value.length;const ids=new Set(items.value.map(row=>row.id));items.value=[...items.value,...result.items.filter(row=>{if(ids.has(row.id))return false;ids.add(row.id);return true;})];page.value=result.page||target;total.value=result.total;hasMore.value=items.value.length>previousCount&&page.value*(result.pageSize||20)<result.total;}catch(e){if(valid(n,s.accessToken))appendError.value=e instanceof Error?e.message:'成员加载失败';}finally{if(n===epoch){loadingMore.value=false;expire(n,s.accessToken);}}}
onReachBottom(()=>{if(!appendError.value)void loadMore();});
function toggle(id:string){if(busy.value)return;selected.value=selected.value.includes(id)?selected.value.filter(v=>v!==id):[...selected.value,id];}
async function loadAdmins(){const s=session(),org=adminOrg.value;if(!s||busy.value)return;if(!org){error.value='当前账号没有学校或机构组织';return;}const n=++epoch;loadingMore.value=false;hasMore.value=false;appendError.value='';busy.value=true;error.value='';admins.value=[];try{const result=await organizationMembersApi.listAdministrators(s.accessToken,org.id);if(valid(n,s.accessToken))admins.value=result;}catch(e){if(valid(n,s.accessToken))error.value=e instanceof Error?e.message:'管理员加载失败';}finally{if(valid(n,s.accessToken))busy.value=false;else expire(n,s.accessToken);}}
function switchAdminTab(value:'SCHOOL'|'INSTITUTION'){if(busy.value)return;adminTab.value=value;loadAdmins();}function openMemberPicker(){if(busy.value)return;view.value='MEMBERS';page.value=1;load();}function backToAdmins(){if(busy.value)return;view.value='ADMINS';loadAdmins();}function chooseOrganization(e:{detail:{value:string}}){if(busy.value)return;organizationIndex.value=Number(e.detail.value);page.value=1;load();}function switchSide(value:'MEMBERS'|'CANDIDATES'){if(busy.value)return;side.value=value;page.value=1;load();}function search(){page.value=1;load();}
async function act(action:MemberAction){const s=session(),org=organization.value;if(!s||!org||busy.value||!selected.value.length||!valid(epoch,s.accessToken))return;const codes:Record<MemberAction,string>={'members:associate':'ORG_MEMBER_ASSOCIATE','members:remove':'ORG_MEMBER_REMOVE','administrators:assign':'ORG_ADMIN_ASSIGN','administrators:revoke':'ORG_ADMIN_REVOKE'};if(!can(codes[action]))return;const ids=selected.value.filter(id=>!items.value.find(i=>i.id===id)?.owner);if(!ids.length)return;const before=epoch;busy.value=true;if(action!=='members:associate'){const result=await uni.showModal({title:'确认组织成员操作',content:`将对选中的 ${ids.length} 位成员执行此操作`,confirmText:'确认'});if(!result.confirm||!valid(before,s.accessToken)){if(before===epoch)busy.value=false;return;}}const n=++epoch;let succeeded=false;error.value="";busy.value=true;try{const me=await meContext(s.accessToken);if(!valid(n,s.accessToken))return;if(!me.permissionCodes.includes(codes[action]))throw new Error('当前操作权限已失效');await organizationMembersApi.action(s.accessToken,org.id,action,ids);if(valid(n,s.accessToken)){succeeded=true;uni.showToast({title:'操作成功',icon:'success'});}}catch(e){if(valid(n,s.accessToken))error.value=e instanceof Error?e.message:'操作失败';}finally{if(valid(n,s.accessToken))busy.value=false;else expire(n,s.accessToken);}if(succeeded&&valid(n,s.accessToken)){if(action==='administrators:assign'&&!parent.value){view.value='ADMINS';await loadAdmins();}else await load();}}
</script>
<style scoped>
.pagination-state{text-align:center;padding:24rpx;color:#7c867d;font-size:25rpx;}.pagination-state button{display:inline-block;}
.secondary-page,.prototype-workspace{padding:24rpx 28rpx 60rpx;min-height:calc(100vh - var(--window-top,0px));box-sizing:border-box;background:#f6f9f5;color:#172e25}.has-footer,.has-tabbar{padding-bottom:160rpx}.prototype-section-header{display:flex;justify-content:center;align-items:center;gap:12rpx;margin:-24rpx -28rpx 24rpx;padding:28rpx;background:linear-gradient(120deg,#206b52,#0c4f3e);color:white;font-size:32rpx;font-weight:650}.section,.form-band,.band,.heading-band{background:#fff;border:1rpx solid #e4ece3;border-radius:24rpx;padding:26rpx;margin-bottom:22rpx}.segmented,.mode-control,.tabs,.action-grid,.form-actions,.paging,.search-row,.two-columns{display:flex;align-items:center;gap:14rpx;margin:18rpx 0}.segmented button,.mode-control button,.tab,.action-grid button{flex:1}.active{background:#e2f2e6;color:#0a774d}.field-label{display:block;font-size:26rpx;margin:20rpx 0 12rpx}.picker-field,.picker-value,.field,input,textarea{background:#f7faf6;border:1rpx solid #dfe8dc;border-radius:16rpx;padding:18rpx;font-size:26rpx;box-sizing:border-box}.picker-field{display:flex;justify-content:space-between}.search-row input{flex:1;min-width:0}textarea{width:100%;min-height:180rpx}.row,.request-person,.invitation-class{display:flex;align-items:center;gap:18rpx;padding:24rpx 0;border-bottom:1rpx solid #e8eee6}.person{width:80rpx;height:80rpx;border-radius:50%;background:#e2eee3;display:flex;align-items:center;justify-content:center;flex-shrink:0}.person-copy{flex:1;min-width:0}.row-top,.section-heading,.detail-line,.list-head{display:flex;justify-content:space-between;align-items:center;gap:12rpx}.name,.section-title,.title,.form-title{font-size:30rpx;font-weight:650}.meta,.small,.counter{display:block;font-size:23rpx;color:#778179;line-height:1.7}.badge,.status{border-radius:12rpx;background:#e2f4e7;color:#13734d;padding:4rpx 12rpx;font-size:23rpx}.PENDING,.submitted{background:#fff0cb;color:#b37a20}.detail-line{font-size:25rpx;padding:15rpx 0}.error,.danger{color:#ac4