.members-nav{position:relative;margin:-24rpx -28rpx 0;padding:24rpx 90rpx;background:linear-gradient(110deg,#206b52,#0c4f3e);color:#fff;text-align:center;font-size:30rpx;font-weight:650}.members-nav .nav-back{position:absolute;left:16rpx;bottom:12rpx;background:transparent;color:#fff;font-size:48rpx;padding:0 12rpx}.admins-page>.section{border:0;border-radius:0;background:transparent;padding:0;margin-bottom:0}.admins-page .segmented{gap:0;border-bottom:1rpx solid #e2eae7;margin:0}.admins-page .segmented button{border-radius:0;background:transparent;flex:1;padding:24rpx 0}.admins-page .segmented button.active{background:transparent;color:#0c5b43;border-bottom:4rpx solid #0c5b43}.admins-page .row{padding:24rpx 0;gap:18rpx}.admins-page .person{width:78rpx;height:78rpx;flex-shrink:0}.admins-page .row-top{gap:8rpx}.admins-page .row-top .name{font-size:27rpx}.admins-page .badge{font-size:19rpx;padding:3rpx 8rpx;border-radius:7rpx}.admins-page .meta{font-size:22rpx;display:block;white-space:nowrap;text-overflow:ellipsis;overflow:hidden;max-width:100%}.admins-page .admin-state{font-size:23rpx}.admins-page>.add-admin-card{margin-top:22rpx;border:1rpx dashed #b7d0c3;border-radius:14rpx;padding:22rpx 20rpx;gap:6rpx}.admins-page .add-plus{font-size:30rpx;line-height:1}.admins-page .add-title{font-size:27rpx}.admins-page .add-note{font-size:22rpx;max-width:460rpx;line-height:1.5}.admins-page .bottom-actions{display:none}
